// con aprobados. Es el ESCALON 5 de la cascada (plan-cascada-de-entrega.md), el ultimo recurso.
const _bu = (x) => x.json._bajo_umbral === true;
// Prioridad del fan-out: (1) aprobado antes que bajo-umbral, (2) relevancia, (3) heat.
// El (1) no es cosmetico: Haiku devuelve `relevante` y `score` POR SEPARADO, asi que un
// `relevante:false` con score 0,7 existe y le ganaria por score a un `relevante:true` con 0,5. Sin
// esta clausula el video cae en la RESERVA de P1 en vez del cupo de P2, que si lo queria, y el
// escalon 5 lo entrega solo cuando P1 quedo corto — o sea que el dedup podia anular la prioridad.
const _mejor = (a, b) => {
  if (_bu(a) !== _bu(b)) return !_bu(a);
  if (_rs(a) !== _rs(b)) return _rs(a) > _rs(b);
  return Number(a.json.heat_score || 0) > Number(b.json.heat_score || 0);
};
const _best = {};
const _copias = {}; // TODAS las copias que pasaron un gate, por video — el insumo del spillover (3)
const _sinId = [];
for (const it of _all) {
  const id = String(it.json.external_id || '');
  if (!id) { _sinId.push(it); continue; }
  (_copias[id] = _copias[id] || []).push(it);
  const prev = _best[id];
  if (!prev || _mejor(it, prev)) _best[id] = it;
}

// 2) CORTE POR PROYECTO, EN DOS ESCALONES (ADR-088 §Enmienda). Cada proyecto llena su N con los
// APROBADOS (PISO primero, despues heat) y recien si quedo corto completa con los bajo-umbral.
// 🔑 Este condicional no podia vivir en el gate: `Gate de relevancia` NO SABE cuanto falta para N
// —ese numero es `_nDe(pid)` y solo existe aca—, asi que ADR-088 dejaba pasar los bajo-umbral
// SIEMPRE, hicieran falta o no. Mani, al verlo: "eso de entregar los 6 rechazados no debe ser".
const _porProy = {};
for (const id in _best) { const it = _best[id]; const pid = String(it.json.proyecto_id || ''); (_porProy[pid] = _porProy[pid] || []).push(it); }
