const _entregados = {}; // pid -> cuantos lleva (corte + spillover); jamas pasa _nDe(pid)
const _sobrantes = []; // ganadores que quedaron afuera porque su proyecto lleno su N
for (const pid in _porProy) {
  const _ordenados = _porProy[pid].sort(_ord);
  const arr = _ordenados.filter(it => !_bu(it));  // escalon 1..4: lo que el gate aprobo
  const _reserva = _ordenados.filter(_bu);        // escalon 5: solo si N queda corto
  const N = _nDe(pid);
  const _sel = new Set();
