}

// 3) SPILLOVER (enmienda ADR-024): un sobrante se entrega al proyecto con cupo que TAMBIEN lo gateo,
// usando LA COPIA DE ESE PROYECTO (su relevancia_score/razon, no los del ganador). GARANTIA dura: un
// video sale en UN solo proyecto — un ganador entregado nunca llega aca, y de las alternativas se
// toma a lo sumo una (break). Sobrantes por heat; alternativas por relevancia (el proyecto que mas lo
// quiso). El PISO no re-aplica aca: el spillover es relleno marginal, no redistribucion.
// La MISMA prioridad del corte, tambien aca: si dos sobrantes se pelean el ultimo cupo de un
// proyecto, primero el aprobado. Dejarlo solo por heat haria que el escalon 5 le ganara un cupo a un
// aprobado por la puerta de atras (ADR-088 §Enmienda).
_sobrantes.sort((a, b) => (_bu(a) !== _bu(b) ? (_bu(a) ? 1 : -1) : _ord(a, b)));
for (const win of _sobrantes) {
  const id = String(win.json.external_id || '');
  const alts = (_copias[id] || []).filter(c => String(c.json.proyecto_id || '') !== String(win.json.proyecto_id || '')).sort((a, b) => (_bu(a) !== _bu(b) ? (_bu(a) ? 1 : -1) : _rs(b) - _rs(a)));
  for (const alt of alts) {
    const pid = String(alt.json.proyecto_id || '');
    if ((_entregados[pid] || 0) >= _nDe(pid)) continue;
    _keep.add(alt);
    _entregados[pid] = (_entregados[pid] || 0) + 1;
    console.log('[Spillover] ' + id + ' → proyecto=' + ((_projects[pid] || {}).nombre || pid) + ' (' + _entregados[pid] + '/' + _nDe(pid) + ')');
    break;
  }
}

// ══ ESCALON 2 (ADR-091) — antes de irse, ofrecerle el video a los proyectos que NO lo reclamaron ══
// Mani: "que se revisen los otros rechazados de otros proyectos para TODOS los proyectos antes de
// irse (basicamente para que todo video tenga chance de matchear a un proyecto)".
//
// El problema que resuelve: `Asignar proyecto+voz` hace el fan-out POR REFERENTE, asi que un video
// solo se le ofrece a los proyectos que reclaman la cuenta que lo publico. Un proyecto que no tiene
// ese referente en su lista NUNCA lo ve, por bien que le calce. Medido el 01/09: el fan-out ofrece
// cada video a ~3,5 proyectos de los 11 activos.
//
// 🔑 POR QUE VIVE ACA y no en un nodo propio: este es el UNICO lugar que sabe las dos cosas que hace
// falta cruzar — quien quedo sin dueno (sale del corte de arriba) y cuanto cupo le queda a cada
// proyecto (`_entregados` vs `_nDe`). Un nodo aparte tendria que RE-IMPLEMENTAR el corte para
// saberlo, y dos implementaciones de la misma regla es el error que plan-orden-y-filtro ya dejo
// escrito. El costo es que este nodo pasa a hacer una llamada paga; por eso es FAIL-OPEN duro.
//
// Costo: SOLO Haiku. El transcript ya esta pagado (ADR-087) y `Transcribir` dedupea por video, asi
// que esto no agrega ni un centavo de ASR.
const _cfg2 = Object.assign({}, $('Config').first().json, (_plan.ajustes || {}));
const CONC2 = Math.max(1, Number(_cfg2.concurrencia_gate || 8));
const BUDGET2 = Math.max(0, Number(_cfg2.presupuesto_2da_s != null ? _cfg2.presupuesto_2da_s : 120)) * 1000;
const CAP2 = Math.max(0, Number(_cfg2.cap_2da_pares != null ? _cfg2.cap_2da_pares : 1500));
const _m2 = { huerfanos: 0, proyectos_con_cupo: 0, pares: 0, chunks: 0, aceptados: 0, sin_presupuesto: 0, por_proyecto: {} };
