  // 1) HUERFANOS: con guion y que no se lleva NADIE. Un video entregado no entra jamas — la garantia
  //    de ADR-018/024 (un video sale en UN solo proyecto) se sostiene contando sobre lo ya elegido.
  const _entregadosIds = new Set();
