  const _huerfanos = [];
  const _vistoPor = {}; // id -> Set(pid) que YA lo juzgaron: a esos no se les vuelve a preguntar
  for (const id in _copias) { (_copias[id] || []).forEach(c2 => { (_vistoPor[id] = _vistoPor[id] || new Set()).add(String(c2.json.proyecto_id || '')); }); }
  const _yaHuerfano = new Set();
  for (const it of _all) {
    const id = String(it.json.external_id || '');
    if (!id || _entregadosIds.has(id) || _yaHuerfano.has(id)) continue;
    if (!String(it.json.script || '').trim()) continue; // ADR-030: sin guion no se juzga
    _yaHuerfano.add(id); _huerfanos.push(it);
  }
  _m2.huerfanos = _huerfanos.length;
  // 2) PROYECTOS CON CUPO. Si nadie tiene cupo no se gasta un centavo: el escalon no corre.
  const _conCupo = Object.keys(_projects).filter(pid => (_entregados[pid] || 0) < _nDe(pid));
  _m2.proyectos_con_cupo = _conCupo.length;
  // 3) PARES a preguntar: (huerfano, proyecto con cupo que NO lo vio y que TIENE criterios).
  const _tareas2 = [];
  for (const pid of _conCupo) {
    const p = _projects[pid] || {};
    const crit = [(p.criterios || ''), (p.voz_criterios || ''), (p.criterios_aprendidos || '')].map(s => String(s).trim()).filter(Boolean);
    if (!crit.length) continue; // sin rubrica no se juzga, igual que el gate
    const suyos = _huerfanos.filter(it => !((_vistoPor[String(it.json.external_id)] || new Set()).has(pid)));
    for (let i = 0; i < suyos.length; i += 25) _tareas2.push({ pid, sub: suyos.slice(i, i + 25) });
  }
  let _pares = 0;
  const _tareasCap = _tareas2.filter(t => { if (_pares + t.sub.length > CAP2) return false; _pares += t.sub.length; return true; });
  _m2.pares = _pares; _m2.chunks = _tareasCap.length;
  if (_tareasCap.length) {
    const _veredicto = {}; // pid -> { id -> {score, razon} }
    const _t0 = Date.now();
    let _n2 = 0;
    const _uno2 = async (t) => {
      const p = _projects[t.pid] || {};
      const criteriosTxt = [p.criterios ? 'CRITERIOS DE TEMA (principal):\n' + p.criterios : '', p.voz_criterios ? 'AJUSTE DE VOZ (complementa, no manda):\n' + p.voz_criterios : '', p.criterios_aprendidos ? 'PATRONES APRENDIDOS (de decisiones reales del equipo; guia, no ley):\n' + p.criterios_aprendidos : ''].filter(Boolean).join('\n\n');
      // Mismo prompt y mismo formato que `Gate de relevancia`, A PROPOSITO: si la rubrica fuera otra,
      // el `relevancia_score` de los que entran por aca no seria comparable con el de los demas y la
      // medicion del norte (ADR-089) mezclaria dos escalas.
      const sys = 'Sos un jurado ESTRICTO de relevancia y calidad. Te doy el tema de un proyecto, sus criterios (el TEMA manda; el AJUSTE DE VOZ solo complementa), y una lista de videos (id + transcript). Para cada uno decidi si es RELEVANTE y UTIL segun los criterios. Precision: ante la duda, marca relevante:false. Devolve UNICAMENTE un JSON {"juicio":[{"id":"...","relevante":true,"score":0.0,"razon":"breve"}]}. score 0..1 = que tan bien cumple los criterios.';
      const usr = 'TEMA: ' + (p.nombre || '') + '\n' + criteriosTxt + '\n\nVIDEOS:\n' + JSON.stringify(t.sub.map(it => ({ id: String(it.json.external_id), texto: String(it.json.script || '').trim().replace(/\s+/g, ' ').slice(0, 1500) })));
      const resp = await this.helpers.httpRequest({
        method: 'POST', url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': '<ANTHROPIC_API_KEY>', 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: { model: 'claude-haiku-4-5', max_tokens: 4000, system: sys, messages: [{ role: 'user', content: usr }] },
        json: true, timeout: 60000
      });
      let txt = ''; try { txt = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) {}
      const m = String(txt).match(/\{[\s\S]*\}/);
      if (!m) return;
      const parsed = JSON.parse(m[0]);
      (parsed.juicio || []).forEach(j => { if (j && j.relevante === true) (_veredicto[t.pid] = _veredicto[t.pid] || {})[String(j.id)] = { score: Number(j.score) || 0, razon: String(j.razon || '') }; });
    };
    const _w2 = async () => { while (_n2 < _tareasCap.length) { const t = _tareasCap[_n2++]; if (BUDGET2 && Date.now() - _t0 > BUDGET2) { _m2.sin_presupuesto++; continue; } try { await _uno2(t); } catch (e) { /* fail-open por chunk */ } } };
