    //    que el dedup y que el spillover). N sigue siendo techo exacto y el video sale en UNO solo.
    const _ofertas = [];
    for (const pid in _veredicto) for (const id in _veredicto[pid]) _ofertas.push({ pid, id, v: _veredicto[pid][id] });
    _ofertas.sort((a, b) => b.v.score - a.v.score);
    const _tomados = new Set();
    for (const o of _ofertas) {
      if (_tomados.has(o.id)) continue;
      if ((_entregados[o.pid] || 0) >= _nDe(o.pid)) continue;
      const base = _huerfanos.find(it => String(it.json.external_id) === o.id);
      if (!base) continue;
      const p = _projects[o.pid] || {};
      // Se CLONA con la identidad del proyecto nuevo: su proyecto/voz, su score y su razon. Sin esto
      // el candidato llegaria con el proyecto que lo descarto, que es peor que no entregarlo.
      // 📏 El prefijo de la razon es como se mide este escalon SIN migracion: los que entraron por
      // aca se leen con `relevancia_razon like '[2da oportunidad]%'` y se cruzan con `calificacion`
      // para el norte de ADR-089. Es la misma jugada con la que ADR-088 se midio sin columna nueva.
      const clon = { json: Object.assign({}, base.json, {
        proyecto_id: o.pid, proyecto_nombre: p.nombre || '',
        voz_id: p.voz_id || base.json.voz_id || null, voz_nombre: p.voz_nombre || base.json.voz_nombre || '',
        relevancia_score: o.v.score, relevancia_razon: '[2da oportunidad] ' + o.v.razon,
        _bajo_umbral: false, _segunda_oportunidad: true
