      _tomados.add(o.id);
      _entregados[o.pid] = (_entregados[o.pid] || 0) + 1;
      _m2.aceptados++;
      _m2.por_proyecto[p.nombre || o.pid] = (_m2.por_proyecto[p.nombre || o.pid] || 0) + 1;
      console.log('[2da oportunidad] ' + o.id + ' → ' + (p.nombre || o.pid) + ' score=' + o.v.score + ' (' + _entregados[o.pid] + '/' + _nDe(o.pid) + ')');
    }
  }
  console.log('[2da oportunidad] ' + JSON.stringify(_m2));
} catch (e) {
  // FAIL-OPEN DURO (invariante #1 de PLAN §2.5): este escalon es relleno. Si Haiku se cae, si el
  // plan viene raro o si algo revienta, la corrida ENTREGA IGUAL lo que ya tenia decidido arriba.
  _m2.error = String((e && e.message) || e);
  console.log('[2da oportunidad] falló y NO frena la entrega: ' + _m2.error);
}

// ADR-086: la HUELLA DE CONTENIDO, lo unico con lo que se reconoce una re-subida del mismo reel.
// El dedup (ADR-029) compara `external_id`, o sea el pk del POST: cuando el creador vuelve a subir
// el mismo video Instagram le da un pk nuevo y el motor lo trae como si no lo hubiera visto nunca.
// Medido el 2026-09-01 sobre 422 candidatos: 17 pares en `candidatos` y 18 mas en `descartes`.
//
// Sale de `d.transcripcion` (el transcript ORIGINAL de Supadata) y NO de `d.script`: `Traducir`
// hace `Object.assign({}, d, {script})`, asi que el original sobrevive al lado del traducido, y es
// el que sirve. El ASR sobre el mismo audio es determinista; la traduccion de Haiku no (medido: el
// hash del guion TRADUCIDO caza 1 de 17 pares, porque Haiku dice 'cuando LLEGA el estres' una vez y
// 'cuando GOLPEA el estres' la otra sobre el MISMO video).
//
