  const _tituloBase = _cortar(String(d.descripcion || '').replace(/\s+/g, ' ').trim(), 80) || (d.username || 'video');
  // ADR-030 (revierte decisión #6): sin transcript se descarta en el Gate y no llega acá. El prefijo
