// Preparar candidatos (D7) — filas planas para PostgREST (ADR-035).
// Se acabaron los `fields`, los links, el `typecast` y los batches de 10: PostgREST acepta el
// array entero de una y `proyecto_id`/`voz_id` son FKs de verdad.
// Los ids del plan YA son los uuid de Postgres, así que el mapa `uuidDe` que traducía desde
// `fields.uuid` murió con el contrato v2 (ADR-048 §5): era identidad desde el paso 3 del corte.
// Sin proyecto resoluble la fila viaja sin él y cae en el grupo `(sin proyecto)` del feed, que es
// visible y raro a propósito — antes, con `typecast: true`, creaba un proyecto FANTASMA en silencio.

// El run abierto por `Abrir run en el registro`, que es ancestro de este nodo (verificado en el
// grafo, igual que `Preparar procesados`). Se lee UNA vez y no por fila.
const _run = $('Abrir run en el registro').first().json || {};

// 🔑 Lee por NOMBRE y no por `$input`: desde ADR-087 este nodo cuelga de `POST processed_items`,
// así que su entrada directa es la respuesta del POST y no los candidatos. Es exactamente el
// mismo movimiento que ADR-084 le hizo a `Traducir` cuando el registro se metió delante suyo.
const filas = $('Armar candidato').all().map(i => {
  const d = i.json;
  return {
    titulo: d.titulo, script: d.script, idioma: d.idioma || null,
    referente: d.referente, url_referente: d.url_referente,
    views: d.views, likes: d.likes, seguidores: d.seguidores, engagement: d.engagement,
    heat_score: d.heat_score, viral_por_tamano: d.viral_por_tamano === true,
    relevancia_score: (d.relevancia_score != null ? d.relevancia_score : null),
    relevancia_razon: d.relevancia_razon || null,
    estado: 'nuevo',
    // De quién es esta fila. Sin esto la 017 la rechaza (not null) y antes de la 017 caería en el
    // default puente al piloto — o sea en la empresa equivocada, en silencio.
    instance_id: $('Config').first().json.instance_id,
    // ADR-029: la 3ª línea de defensa del dedup. Desde D7 la columna tiene UNIQUE, así que el
    // duplicado lo frena la base y no una comparación en JS (`Prefer: ignore-duplicates`).
    external_id: d.external_id || null,
    // La URL cruda del CDN. Airtable la re-hosteaba; ahora nadie: viene firmada y con expiry, y
    // la tarjeta del feed cae a su placeholder cuando vence (hallazgo 2 de D7).
    thumbnail_url: d.thumbnail_url || null,
    proyecto_id: d.proyecto_id || null,
    voz_id: d.voz_id || null,
    // ADR-081: de qué corrida salió. `|| null` y no un throw — `Abrir run en el registro` es
    // SUMIDERO (invariante #1 de PLAN §2.5), así que si el registro se cayó la corrida entrega
    // igual y el candidato nace sin corrida. Misma forma que `Armar filas archivado`.
    // 🔴 NO se deriva de `creado_en` en el cockpit: medido el 2026-08-30, el 40% de los candidatos
    // vivos (68 de 168) cae fuera de toda ventana de corrida — son el rescate manual del 22/08, y
    // su `creado_en` es la hora del rescate, no la de la corrida que los produjo.
    run_id: (_run.id || null),
    // ADR-086 (migracion `036`). NO las lee nadie todavia: existen para poder medir si alguna
    // aguanta un bloqueo pre-pago en `Heat-score v1`. `duracion_seg` es la unica senal de contenido
    // disponible ANTES de pagarle a Supadata, y hasta hoy `Normalizar IG` la producia y nadie la
    // guardaba. `|| null` en las dos y no un throw: son datos de medicion y no pueden tumbar la
    // entrega (invariante #1 de PLAN §2.5) — misma forma que `run_id`.
    duracion_seg: (d.duracion_seg != null ? d.duracion_seg : null),
    huella_guion: d.huella_guion || null,
    // ADR-092 (migracion `038`). LA ETIQUETA: la metrica cruda del video, que hasta hoy se moria en
    // el gate — `Gate de relevancia` pisa `heat_score` con su veredicto y nadie guardaba el otro
    // numero. No se puede recomputar despues: es un PERCENTIL relativo al pool de SU corrida.
    // `|| null` y no un throw: es dato de medicion y no puede tumbar la entrega (invariante #1),
    // misma forma que `run_id` y `duracion_seg`.
    prescore_metrico: (d.prescore_metrico != null ? d.prescore_metrico : null)
  };
});
const _sinProy = filas.filter(f => !f.proyecto_id).length;
if (_sinProy) console.log('[Entrega] ⚠️ ' + _sinProy + ' candidato(s) sin proyecto resoluble');
console.log('[Entrega] ' + filas.length + ' candidatos a Postgres');
return filas.length ? [{ json: { filas } }] : [];

// La memoria del dedup. Desde ADR-087 contesta UNA sola pregunta: **¿esto ya se lo mostré al
// equipo?**
//
// 🩸 Antes contestaba *"¿ya lo evalué?"*: colgaba de `Transcribir` y quemaba todo lo que Supadata
// resolviera, pasara o no al Feed. Medido el 2026-09-01 contra prod: de **1.952** filas, **1.401
// (71,8%) eran de videos que nunca vio nadie**. Los mataba el gate o el corte por N —después de
// haberlos pagado— y no volvían nunca. Ahora este nodo cuelga de `Armar candidato`, o sea de lo
// que de verdad se entrega.
//
// 🔑 Lo que NO se entregó vuelve la próxima corrida, y vuelve **gratis**: su transcripción quedó en
// `app.transcripciones` (ADR-087 §1). Ese orden es el corazón de la ADR — sin la caché, dejar de
// quemar sería re-pagarle a Supadata en cada corrida, para siempre. La caché va primero y el
// movimiento después.
//
// El guard sigue siendo DURO, por el mismo motivo que en ADR-084: si alguien recablea este nodo, el
// modo de falla es quedarse sin memoria y que la corrida siguiente re-entregue todo, en verde.
const cfg = $('Config').first().json;
const iid = cfg.instance_id || null;
let rid = null;
try { rid = $('Abrir run en el registro').first().json.id || null; } catch (e) {}
const _entrada = $input.all();
// 🔑 El guard mira la PRESENCIA de la clave, no su valor, y la diferencia importa: con el valor
// no se puede distinguir "me cablearon mal" de "esta corrida no entregó nada", y la segunda es
// un caso legítimo. Es el mismo guard que ADR-084 escribió para `_tx_resuelta`.
if (_entrada.length && !_entrada.some(i => i.json && '_entregado' in i.json)) {
  throw new Error('[Dedup] ningun item trae _entregado: Preparar procesados no esta colgando de Armar candidato — abortando para no quedarme sin memoria de dedup (ADR-087)');
}
const vistos = new Set();
const batch = [];
for (const i of _entrada) {
  const dd = i.json || {};
  if (dd._entregado !== true) continue;
  const id = String(dd.external_id || '');
  // Sin external_id no hay nada que recordar. `Armar candidato` los deja pasar (fail-open) y acá
  // simplemente no se queman: van al Feed y la corrida siguiente los puede volver a traer.
  if (!id || vistos.has(id)) continue;
  vistos.add(id);
  // Solo lo que el dedup necesita. Las 4 columnas que nadie leía las dropeó la `023` (ADR-059), y
  // mandarlas de nuevo haría que PostgREST rechace el insert entero con PGRST204 — que el
  // `onError: continue` del POST se traga, dejando la corrida en verde SIN memoria.
  batch.push({ instance_id: iid, run_id: rid, platform: dd.plataforma || '', external_id: id });
}
console.log('[Dedup] quemando ' + batch.length + ' videos ENTREGADOS; lo descartado NO se quema y vuelve la proxima corrida (ADR-087)');
return [{ json: { batch } }];

// 🩸 Mismo corte seguro que `Armar candidato`, y por la misma razón: `.slice(0,80)` corta UTF-16 y
// puede dejar medio emoji, que no es UTF-8 válido y le da a PostgREST un 400 `Empty or invalid json`.
// Acá **todavía no explotó**, y eso es suerte y no diseño: es el mismo POST contra la misma base.
const _cortar = (s, n) => Array.from(String(s == null ? '' : s)).slice(0, n).join('');
// Descartes del gate visibles (ADR-021): sube SOLO la banda borderline que el gate marcó con
// _descarte. El equipo audita y marca 'veredicto'; de ahí sale `falsos_negativos`.
// ADR-030: los descartes por sin_guion NO van acá (la tabla es para auditar el criterio, no
// videos mudos).
// ⚠️ D7/ADR-036: esta tabla YA NO SE BARRE los domingos. Un descarte sin auditar dejó de ser una
// auditoría perdida para siempre.
// Los ids del plan YA son los uuid de Postgres, así que el mapa `uuidDe` que traducía desde
// `fields.uuid` murió con el contrato v2 (ADR-048 §5): era identidad desde el paso 3 del corte.
// Sin proyecto resoluble la fila viaja sin él y cae en el grupo `(sin proyecto)` del feed, que es
// visible y raro a propósito — antes, con `typecast: true`, creaba un proyecto FANTASMA en silencio.

const items = $('Gate de relevancia').all().map(i => i.json).filter(d => d._descarte && d.descarte_razon !== 'sin_guion');
const filas = items.map(d => ({
  titulo: _cortar(String(d.descripcion || '').replace(/\s+/g, ' ').trim(), 80) || (d.username || 'video'),
  script: _cortar(d.script, 95000),
  referente: d.username || '', url_referente: d.url || '',
  relevancia_score: (d.relevancia_score != null ? d.relevancia_score : null),
  relevancia_razon: d.relevancia_razon || null,
  thumbnail_url: d.thumbnail_url || null,
  proyecto_id: d.proyecto_id || null,
  // ADR-087 (migracion 037). Sin esto un descarte NO se puede volver a encontrar: hasta hoy
  // `rescatar-huerfanos.mjs` tenia que decodificar el shortcode desde `url_referente` para
  // reconstruirlo. Todo video en la herramienta se identifica por (plataforma, external_id).
  external_id: d.external_id || null,
  instance_id: $('Config').first().json.instance_id
}));
console.log('[Descartes] ' + filas.length + ' a auditar');
return filas.length ? [{ json: { filas } }] : []; // [] si no hay borderline: el POST no corre

// Resumen del run (ADR-021) — arma runs.metricas: embudo + sin_guion + llamadas estimadas por
// servicio + desglose por referente (evaluados/gate_pass en videos DISTINTOS; habilita la higiene
// de fuentes de ADR-022). Cerrar run persiste $json.metricas tal cual.
const gateAll = $('Gate de relevancia').all();
const gateKept = gateAll.filter(i => !i.json._descarte);
const outputs = $('Armar candidato').all();
const gateIn = $('Traducir (Claude Haiku)').all();
const _distinct = (items) => new Set(items.map(i => String(i.json.external_id || '')).filter(Boolean)).size;
const _lotes = (items) => new Set(items.map(i => String(i.json.proyecto_id || '')).filter(Boolean)).size;
// llamadas estimadas: Supadata = videos distintos transcritos (dedup intra-corrida, ADR-016);
// Haiku: pre-trim = 1 lote/proyecto (cota superior: exentos/sin-criterios no llaman), gate = chunks
// de a 25 por proyecto (cierre 31), traducciones = videos DISTINTOS no-ES (Traducir dedupea, cierre 31).
const _lotesChunk = (items, chunk) => { const by = {}; items.forEach(i => { const p = String(i.json.proyecto_id || ''); if (p) by[p] = (by[p] || 0) + 1; }); return Object.values(by).reduce((a, n) => a + Math.ceil(n / chunk), 0); };
const llamadas = {
  supadata: _distinct($('Transcribir (Supadata)').all()),
  // 🩸 Decía `_lotes(...)` = 1 llamada por proyecto, que era verdad hasta que el pre-trim se
  // chunkeó (ADR-044 §Enmienda). Medido en la ejecución 156: informaba **4** llamadas y la corrida
  // hizo ~38 ⇒ subestimaba el costo casi 10x. Sigue siendo una COTA SUPERIOR, igual que antes: los
  // captions pobres y los proyectos sin criterios no llaman. El 100 es el `CHUNK` del pre-trim, y
  // está duplicado acá igual que el 25 del gate — si allá cambia, acá también.
  haiku_lotes_pretrim: _lotesChunk($('Asignar proyecto+voz').all(), 100),
  haiku_lotes_gate: _lotesChunk(gateIn, 25),
  haiku_traducciones: new Set(gateIn.filter(i => String(i.json.transcripcion || '').trim() && (i.json.idioma || 'es') !== 'es').map(i => String(i.json.external_id || i.json.url || '')).filter(Boolean)).size
};
const por_referente = {};
const _mark = (items, key) => { const seen = new Set(); for (const it of items) { const u = String(it.json.username || '').toLowerCase(); const id = String(it.json.external_id || ''); if (!u || !id) continue; const k = u + '|' + id; if (seen.has(k)) continue; seen.add(k); (por_referente[u] = por_referente[u] || { evaluados: 0, gate_pass: 0 })[key]++; } };
_mark(gateIn, 'evaluados');
_mark(gateKept, 'gate_pass');
const _n = (name) => { try { return $(name).all().length; } catch (e) { return 0; } };
// Verificacion de la escritura de memoria (ADR-029): con el reorden de ramas, POST processed_items
// ya ejecuto cuando corre el Resumen. Si fallo, el proximo run depende solo del feed vivo.
let registro_dedup = 'no_corrio';
try { const _r = $('POST processed_items').all(); registro_dedup = _r.some(i => i && i.json && i.json.error) ? 'fallo' : 'ok'; } catch (e) {}
const avisos = [];
if (registro_dedup === 'fallo') avisos.push('processed_items no se escribio: el proximo run dependeria del feed vivo para no duplicar');
// Avisos que NACEN en otro nodo y este solo reenvia: el que sabe por que se recorto es el que
// recorta. Hoy el unico es el clamp de 'Resultados por cuenta de referente', que hasta el 31/08
// bajaba el numero en silencio.
try { (($('Armar plan de corrida').first().json || {}).avisos || []).forEach(a => avisos.push(String(a))); } catch (e) {}
// Un gate que no llego a juzgar y un gate generoso entregan lo mismo y se leen IDENTICO en la
// pantalla: los dos dejan pasar. Sin este contador, quedarse sin presupuesto es invisible.
const gate_sin_presupuesto = new Set(gateAll.filter(i => i.json._gate_sin_presupuesto === true).map(i => String(i.json.external_id || '')).filter(Boolean)).size;
if (gate_sin_presupuesto > 0) avisos.push('el gate se quedo sin presupuesto: ' + gate_sin_presupuesto + ' videos entraron al feed SIN juicio de relevancia (pasaron por metrica). Subir concurrencia_gate o presupuesto_gate_s');
// Mismo principio que el de arriba, un paso mas temprano: "no habia nada off-topic" y "no pude
// mirar" entregan lo mismo. Medido el 31/08: dos proyectos de 465 videos descartaron CERO y no
// habia forma de saber cual de las dos cosas era.
const pretrim_sin_juicio = new Set($('Pre-trim relevancia').all().filter(i => i.json._pretrim_fallo === true).map(i => String(i.json.external_id || '')).filter(Boolean)).size;
if (pretrim_sin_juicio > 0) avisos.push('el pre-trim no pudo juzgar ' + pretrim_sin_juicio + ' videos (Haiku cayo o la respuesta vino truncada): pasaron sin filtrar y se les paga la transcripcion');
// El techo de Supadata asomando. Se cuenta por VIDEO DISTINTO (el fan-out repite la fila) y suma
// tambien los rechazos que el backoff recupero: son los que dicen cuanto aire queda para subir
// `concurrencia_transcribir`, y no aparecen en ningun otro numero de esta corrida.
const _r429 = new Map();
for (const i of $('Transcribir (Supadata)').all()) { const id = String(i.json.external_id || ''); if (id && !_r429.has(id)) _r429.set(id, Number(i.json._tx_429 || 0)); }
const rechazos_supadata = [..._r429.values()].reduce((a, n) => a + n, 0);
const videos_con_rechazo = [..._r429.values()].filter(n => n > 0).length;
if (videos_con_rechazo > 0) avisos.push('Supadata rechazo ' + rechazos_supadata + ' pedidos sobre ' + videos_con_rechazo + ' videos: el backoff los absorbio, pero la concurrencia esta tocando el techo. No subirla mas sin volver a medir');
// ADR-030: transcripciones vacias (videos DISTINTOS sin transcript a la salida de Transcribir) — la
// causa raiz de los sin-guion. Aviso si domina la corrida (probable caida de Supadata).
const _vacias = new Set($('Transcribir (Supadata)').all().filter(i => !String(i.json.transcripcion || '').trim()).map(i => String(i.json.external_id || '')).filter(Boolean)).size;
const sinGuionDesc = gateAll.filter(i => i.json._descarte && i.json.descarte_razon === 'sin_guion');
if (llamadas.supadata > 0 && _vacias / llamadas.supadata > 0.5) avisos.push('posible caida de Supadata: ' + Math.round(_vacias / llamadas.supadata * 100) + '% de transcripciones vacias esta corrida');
// ADR-030/Fase 3: tasa de gate POR PROYECTO — responde "mi criterio mata demasiado?". Todo de nodos
// ya referenciados; runs.metricas es jsonb (cero cambio de schema). Cerrar run lo persiste tal cual.
const _plan = $('Armar plan de corrida').first().json || {};
const _planProj = _plan.projects || {};
const _distBy = (items, pred) => { const m = {}; for (const it of items) { const pid = String(it.json.proyecto_id || ''); if (!pid) continue; if (pred && !pred(it)) continue; const id = String(it.json.external_id || ''); if (!id) continue; (m[pid] = m[pid] || new Set()).add(id); } return m; };
const _evalBy = _distBy(gateIn);
const _sinGuionBy = _distBy(gateIn, i => !String(i.json.script || '').trim());
const _gatePassBy = _distBy(gateKept);
const por_proyecto = {};
const _pids = new Set(Object.keys(_planProj)); gateIn.forEach(i => { const p = String(i.json.proyecto_id || ''); if (p) _pids.add(p); });
for (const pid of _pids) {
  const ev = _evalBy[pid] ? _evalBy[pid].size : 0;
  const sg = _sinGuionBy[pid] ? _sinGuionBy[pid].size : 0;
  const gp = _gatePassBy[pid] ? _gatePassBy[pid].size : 0;
  const conGuion = Math.max(0, ev - sg);
  const ent = outputs.filter(o => String(o.json.proyecto_id || '') === pid).length;
  const nObj = Number((_planProj[pid] || {}).n || 0);
  const tasa_gate = conGuion > 0 ? Math.round(gp / conGuion * 100) / 100 : null;
  let razon_faltante = null;
  if (nObj > 0 && ent < nObj) {
    const supplyThin = conGuion < 4 * nObj; // con gate ~25% hacen falta ~4N con guion para llenar N
    const gateHarsh = conGuion > 0 && (gp / conGuion) < 0.15;
    razon_faltante = (gateHarsh && supplyThin) ? 'mixta' : (gateHarsh ? 'gate' : 'supply');
  }
  por_proyecto[pid] = { nombre: (_planProj[pid] || {}).nombre || pid, n_objetivo: nObj, evaluados: ev, sin_guion: sg, gate_pass: gp, tasa_gate, entregados: ent, razon_faltante };
}
const metricas = {
  colectados: $('Merge scrapes').all().length,
  apify_ig: _n('Apify — IG Reels'),
  apify_tt: _n('Apify — TikTok Perfil'),
  asignados: $('Asignar proyecto+voz').all().length,
  pretrim: $('Pre-trim relevancia').all().length,
  filtrados: $('Heat-score v1').all().length,
  gate: gateKept.length,
  outputs: outputs.length,
  sin_guion: new Set(sinGuionDesc.map(i => String(i.json.external_id || '')).filter(Boolean)).size, // ADR-030: ahora = videos descartados por sin-guion (antes: entregados sin guion, hoy siempre 0)
  transcripciones_vacias: _vacias,
  descartes_expuestos: gateAll.filter(i => i.json._descarte && i.json.descarte_razon !== 'sin_guion').length,
  gate_sin_presupuesto, pretrim_sin_juicio, rechazos_supadata, videos_con_rechazo,
  // Pendiente #9 del audit: `filtrados` es UN numero para TRES filtros (dedup + min_views +
  // min_likes) y por eso los miles que mueren ahi eran anonimos. Ahora se sabe cual mato cual, con
  // los pisos vigentes al lado — sin ellos el numero no se puede interpretar el mes que viene.
  filtrados_por_motivo: (() => { try { return ($('Heat-score v1').first().json || {})._muertos || null; } catch (e) { return null; } })(),
  // ADR-088. Cuantos entraron al Feed que el gate viejo habria tirado. Es LA metrica que decide si
  // el veto servia: se cruza despues con la calificacion del equipo. Videos DISTINTOS, no filas.
  bajo_umbral: new Set(gateKept.filter(i => i.json._bajo_umbral === true).map(i => String(i.json.external_id || '')).filter(Boolean)).size,
  // ADR-088 §Enmienda: desde el escalon 5, ADMITIDO y ENTREGADO bajo umbral dejaron de ser el mismo
  // numero — el gate admite todo y `Armar candidato` los usa solo si N quedo corto. Sin este
  // contador, `bajo_umbral: 40` se sigue leyendo como "40 dudosos en el Feed" cuando pueden ser 2.
  // ADR-091. Mani pidió explícito que el escalón 2 entre CON su seguimiento: "es clave; toca hacer
  // seguimiento de si esto sirve o no". Este cuenta cuántos entraron por ahí; el norte de ADR-089
  // para ESOS se lee cruzando `relevancia_razon like '[2da oportunidad]%'` con `calificacion`, sin
  // migración. Si esto da 0 corrida tras corrida, el escalón no es la palanca y hay que decirlo.
  segunda_oportunidad: new Set(outputs.filter(i => i.json._segunda_oportunidad === true).map(i => String(i.json.external_id || '')).filter(Boolean)).size,
  bajo_umbral_entregados: new Set(outputs.filter(i => i.json._bajo_umbral === true).map(i => String(i.json.external_id || '')).filter(Boolean)).size,
  llamadas, por_referente, por_proyecto,
  registro_dedup, avisos
};
console.log('[Resumen] ' + JSON.stringify(metricas));
return [{ json: { metricas } }];

parameters.jsonBody:
={{ (function(){
var g = function(n){ try { return $(n).all().length; } catch (e) { return 0; } };
var mirados = g('Pre-trim relevancia');
return { fin: $now.toISO(), estado: 'ok', metricas: {
  colectados: g('Merge scrapes'), apify_ig: g('Apify — IG Reels'), apify_tt: g('Apify — TikTok Perfil'),
  asignados: g('Asignar proyecto+voz'), pretrim: mirados,
  filtrados: 0, gate: 0, outputs: 0, sin_guion: 0, transcripciones_vacias: 0,
  descartes_expuestos: 0, gate_sin_presupuesto: 0, pretrim_sin_juicio: 0,
  rechazos_supadata: 0, videos_con_rechazo: 0,
  llamadas: { supadata: 0, haiku_lotes_pretrim: 0, haiku_lotes_gate: 0, haiku_traducciones: 0 },
  por_referente: {}, por_proyecto: {}, registro_dedup: 'no_corrio',
  sin_novedades: true,
  avisos: ['sin novedades: se miraron ' + mirados + ' videos y ninguno era nuevo. No se transcribio ni se pago nada.']
} };
})() }}

parameters.jsCode:
// Arma el body de `app.cache_transcripts` (ADR-087). UN solo item.
//
// 🔑 Los ids van en el BODY y no en la URL a propósito: con ~350 ids un GET a PostgREST devuelve
// **414** en producción. Es el mismo límite que obligó a `apps/dashboard/lib/transcripciones.ts` a
// trocear de a 200, y `cap_top_n` está en 350. La otra salida era meter un secreto de Supabase en
// este code node (los Code nodes de n8n no pueden usar credenciales) y se descartó.
//
// Se piden los external_id distintos de ESTA corrida, leídos de `Heat-score v1` — la misma fuente y
// la misma llave que usa `Transcribir`. Si acá se leyera otro nodo, la caché fallaría en silencio:
// pediría por unos ids y se aplicaría sobre otros.
const cfg = $('Config').first().json;
const ids = []; const vistos = new Set();
for (const it of $('Heat-score v1').all()) {
  const id = String(it.json.external_id || '');
  if (!id || vistos.has(id)) continue;
  vistos.add(id); ids.push(id);
}
console.log('[Cache] consultando ' + ids.length + ' videos distintos');
return [{ json: { p_instance: cfg.instance_id || null, p_ids: ids } }];

// Guarda en `app.transcripciones` lo que ESTA corrida le pagó a Supadata, para que ninguna corrida
// futura lo vuelva a pagar (ADR-087).
//
// Es el libro del ASR, no el del dedup. Acá se anota **"pagué"**; en `processed_items` se anota
// **"se lo mostré al equipo"**. Separarlos es toda la ADR: hasta hoy una sola marca contestaba las
// dos preguntas, y por eso 1.401 de 1.952 videos quemados (71,8%) nunca se le mostraron a nadie.
//
// Qué entra y qué no:
//   · sólo lo RESUELTO (`_tx_resuelta`), con el criterio de ADR-084 — un 429 o un presupuesto
//     agotado NO son una respuesta, y anotarlos cachearía un vacío para siempre.
//   · sólo lo que vino de Supadata (`_tx_origen === 'supadata'`): un cache hit ya está en la tabla.
//   · `estado` distingue las dos respuestas definitivas: con texto es `listo`; sin texto es
//     `sin_transcript` — el video no tiene audio, y ese dato vale tanto como el guion porque evita
//     volver a preguntarlo en cada corrida futura.
//   · `origen: 'motor'` es lo que mantiene la pantalla del equipo limpia. Las 5 lecturas del
//     cockpit filtran `manual`; sin esta marca, estas filas caen en su lista de fallidas con un
//     botón `Reintentar` que no tiene nada que reintentar.
const cfg = $('Config').first().json;
const iid = cfg.instance_id || null;
const PLATAFORMAS = new Set(['instagram', 'tiktok']); // el enum de la tabla, ni uno más
const vistos = new Set();
const filas = [];
let _incompletos = 0;
for (const it of $('Transcribir (Supadata)').all()) {
  const d = it.json;
  const id = String(d.external_id || '');
  if (!id || vistos.has(id)) continue;         // el fan-out repite el mismo video
  if (d._tx_resuelta !== true) continue;        // sin respuesta definitiva no se cachea
  if (d._tx_origen !== 'supadata') continue;    // ya estaba en la tabla
  const plat = String(d.plataforma || '').toLowerCase();
  const url = String(d.url || d.video_url || '');
  // `plataforma`, `external_id`, `url` e `instance_id` son NOT NULL y `plataforma` es un enum:
  // una fila incompleta no rebota sola, se lleva puesto el INSERT ENTERO (PostgREST manda el array
  // en una transacción). Se filtra acá y se avisa, en vez de perder el lote.
  if (!PLATAFORMAS.has(plat) || !url || !iid) { _incompletos++; continue; }
  vistos.add(id);
  const txt = String(d.transcripcion || '').trim();
  filas.push({
    instance_id: iid,
    plataforma: plat,
    external_id: id,
    url: url,
    estado: txt ? 'listo' : 'sin_transcript',
    script: txt || null,
    idioma: d.idioma_detectado || null,
    origen: 'motor',
    procesado_en: new Date().toISOString()
  });
}
if (_incompletos) console.log('[Cache] ' + _incompletos + ' sin plataforma/url/instancia: no se cachean (se re-pagarian, no se pierden)');
console.log('[Cache] guardando ' + filas.length + ' transcripciones nuevas');
// SIEMPRE un item, aunque `filas` vaya vacío: la cadena sigue hacia `Traducir`, y cortarla acá
// dejaría la corrida sin traducir ni juzgar nada. Mismo criterio que `Preparar procesados`.
return [{ json: { filas } }];
